    if (recipes.length === 0) {
      throw new Error(`craftLocal: no hand recipe for "${itemName}" (missing ingredients?) after ${i}/${amount} crafted`);
    }
    await bot.craft(recipes[0], 1, undefined);
  }
  return { item: itemName, amount };
}

